{"explanation":"At each peg, a ball randomly falls left or right. After 8 rows, its final bin equals the number of right turns, so the probability of landing in bin k is binomial: P(X=k)=C(8,k)p^k(1−p)^(8−k). Watch the blue histogram build up against the orange theoretical probabilities, then change the right-turn probability or release more balls.","manimCode":"const rows = 8;
const boardX = -3.5;
const gap = 0.48;
let probability = 0.5;
let counts = Array(rows + 1).fill(0);
let total = 0;
let busy = false;
let seed = 7391;
function randomValue() {
  seed = (1664525 * seed + 1013904223) >>> 0;
  return seed / 4294967296;
}
function choose(n, k) {
  let result = 1;
  for (let j = 1; j <= k; j++) result *= (n - j + 1) / j;
  return result;
}
function binProbability(k) {
  return choose(rows, k) * Math.pow(probability, k) * Math.pow(1 - probability, rows - k);
}

const title = new Text({ text: 'Galton board → binomial distribution', fontSize: 30, color: WHITE });
title.moveTo([0, 3.35, 0]);
const boardTitle = new Text({ text: '8 independent left / right choices', fontSize: 19, color: GRAY });
boardTitle.moveTo([boardX, 2.85, 0]);
const graphTitle = new Text({ text: 'Observed frequency vs. probability', fontSize: 19, color: WHITE });
graphTitle.moveTo([3, 2.5, 0]);
scene.add(title, boardTitle, graphTitle);

const pegs = [];
for (let row = 0; row < rows; row++) {
  for (let j = 0; j <= row; j++) {
    const peg = new Dot({ point: [boardX + (j - row / 2) * gap, 2.2 - row * 0.44, 0], color: GRAY });
    peg.scale(0.48);
    pegs.push(peg);
  }
}
const pegGroup = new VGroup(...pegs);
await scene.play(new FadeIn(pegGroup));
const floorY = -2.05;
const floor = new Line({ start: [boardX - 4.5 * gap, floorY, 0], end: [boardX + 4.5 * gap, floorY, 0], color: GRAY });
scene.add(floor);
for (let j = 0; j <= 9; j++) {
  const wallX = boardX + (j - 4.5) * gap;
  scene.add(new Line({ start: [wallX, floorY, 0], end: [wallX, -1.55, 0], color: GRAY }));
}
for (let k = 0; k <= rows; k++) {
  const binLabel = new Text({ text: String(k), fontSize: 16, color: WHITE });
  binLabel.moveTo([boardX + (k - 4) * gap, -2.3, 0]);
  scene.add(binLabel);
}
const boardCaption = new Text({ text: 'Final bin = number of right turns', fontSize: 17, color: GRAY });
boardCaption.moveTo([boardX, -2.75, 0]);
scene.add(boardCaption);

const axes = new Axes({ xRange: [-0.5, 8.5, 1], yRange: [0, 0.4, 0.1], xLength: 5, yLength: 4, tips: false });
axes.moveTo([3, -0.15, 0]);
await scene.play(new Create(axes));
for (let k = 0; k <= rows; k++) {
  const tickLabel = new Text({ text: String(k), fontSize: 16, color: WHITE });
  tickLabel.moveTo(axes.c2p(k, 0));
  tickLabel.shift([0, -0.23, 0]);
  scene.add(tickLabel);
}
for (const value of [0.1, 0.2, 0.3, 0.4]) {
  const tickLabel = new Text({ text: value.toFixed(1), fontSize: 14, color: GRAY });
  tickLabel.moveTo(axes.c2p(-0.5, value));
  tickLabel.shift([-0.23, 0, 0]);
  scene.add(tickLabel);
}
const blueKey = new Text({ text: 'Blue: balls', fontSize: 17, color: BLUE });
blueKey.moveTo([1.7, 2.1, 0]);
const goldKey = new Text({ text: 'Orange: theory', fontSize: 17, color: ORANGE });
goldKey.moveTo([4.25, 2.1, 0]);
scene.add(blueKey, goldKey);

let barGroup = null;
let theoryGroup = null;
let statusLabel = null;
function updateHistogram() {
  if (barGroup) scene.remove(barGroup);
  const bars = [];
  for (let k = 0; k <= rows; k++) {
    const height = total ? counts[k] / total : 0;
    const bar = new Polygon({ vertices: [axes.c2p(k - 0.36, 0), axes.c2p(k + 0.36, 0), axes.c2p(k + 0.36, height), axes.c2p(k - 0.36, height)], color: BLUE });
    bar.setFill(BLUE, 0.65);
    bar.setStrokeWidth(1);
    bars.push(bar);
  }
  barGroup = new VGroup(...bars);
  scene.add(barGroup);
  // Re-add theory above the bars so the comparison stays visible.
  if (theoryGroup) {
    scene.remove(theoryGroup);
    scene.add(theoryGroup);
  }
  if (statusLabel) scene.remove(statusLabel);
  statusLabel = new Text({ text: total + ' balls   |   P(right) = ' + probability.toFixed(2), fontSize: 18, color: WHITE });
  statusLabel.moveTo([3, -2.8, 0]);
  scene.add(statusLabel);
}
function updateTheory() {
  if (theoryGroup) scene.remove(theoryGroup);
  const marks = [];
  for (let k = 0; k <= rows; k++) {
    const y = binProbability(k);
    const cap = new Line({ start: axes.c2p(k - 0.4, y), end: axes.c2p(k + 0.4, y), color: ORANGE });
    cap.setStrokeWidth(3);
    marks.push(cap);
    const marker = new Dot({ point: axes.c2p(k, y), color: ORANGE });
    marker.scale(0.55);
    marks.push(marker);
  }
  theoryGroup = new VGroup(...marks);
  scene.add(theoryGroup);
}
updateTheory();
updateHistogram();
const formula = new MathTex({ latex: 'P(X=k)=\\binom{8}{k}p^k(1-p)^{8-k},\\qquad k=0,\\ldots,8' });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([0, -3.35, 0]);
await scene.play(new Write(formula));

async function releaseWave(amount) {
  const balls = [];
  const paths = [];
  for (let b = 0; b < amount; b++) {
    const jitter = (randomValue() - 0.5) * 0.13;
    let rights = 0;
    const path = [];
    for (let row = 0; row < rows; row++) {
      if (randomValue() < probability) rights++;
      path.push([boardX + (rights - (row + 1) / 2) * gap + jitter, 1.98 - row * 0.44, 0]);
    }
    path.push([boardX + (rights - 4) * gap + jitter, -1.9, 0]);
    paths.push({ points: path, bin: rights });
    const ball = new Dot({ point: [boardX + jitter, 2.48, 0], color: BLUE });
    ball.scale(0.65);
    balls.push(ball);
  }
  scene.add(...balls);
  for (let step = 0; step <= rows; step++) {
    const moves = balls.map((ball, i) => {
      const from = ball.getCenter();
      const destination = paths[i].points[step];
      return new Shift(ball, { direction: [destination[0] - from[0], destination[1] - from[1], 0] });
    });
    await scene.play(new AnimationGroup(moves));
  }
  for (const path of paths) { counts[path.bin]++; total++; }
  updateHistogram();
  await scene.wait(0.25);
  scene.remove(...balls);
}

busy = true;
for (let wave = 0; wave < 3; wave++) await releaseWave(20);
busy = false;

const controls = new Controls(scene, { position: 'bottom-left', width: 265 });
controls.addSlider({ label: 'Probability of right turn', min: 0.2, max: 0.8, step: 0.05, value: 0.5, onChange: (value) => {
  if (busy) return;
  probability = value;
  counts = Array(rows + 1).fill(0);
  total = 0;
  updateTheory();
  updateHistogram();
} });
controls.addButton({ label: 'Animate 20 more balls', onClick: async () => {
  if (busy) return;
  busy = true;
  try { await releaseWave(20); } finally { busy = false; }
} });
controls.addButton({ label: 'Add 500 balls instantly', onClick: () => {
  if (busy) return;
  for (let b = 0; b < 500; b++) {
    let rights = 0;
    for (let row = 0; row < rows; row++) if (randomValue() < probability) rights++;
    counts[rights]++;
    total++;
  }
  updateHistogram();
} });
controls.addButton({ label: 'Clear histogram', onClick: () => {
  if (busy) return;
  counts = Array(rows + 1).fill(0);
  total = 0;
  updateHistogram();
} });
await scene.wait(999999);"}

